python3 -c "
import sys; sys.path.insert(0, '/private/tmp/dn-live-5v9d_x0s/workspace')
from boltons.iterutils import get_path, PathAccessError
root = {'a': {'b': {'c': [[1],[2],[3]]}}}
print('docstring tuple:', get_path(root, ('a','b','c',2,0)))
print('docstring dotted:', get_path(root, 'a.b.c.2.0'))
print('dotted list idx:', get_path({'key': ['test']}, 'key.0'))
print('tuple root:', get_path(('x', ('y','z')), (1,1)), get_path(('x', ('y','z')), '1.1'))
print('default:', get_path(root, ('a','nope'), default='DEF'))
s = object(); print('default sentinel:', get_path(root, ('nope',), default=s) is s)
try:
    get_path({'a': {}, 'b': 1}, ('a','b'))
except PathAccessError as e:
    print('outer-root trap:', repr(e), '| exc:', repr(e.exc), '| seg:', e.seg, '| path:', e.path, '| isinstance:', isinstance(e, (KeyError, IndexError, TypeError)))
try:
    get_path({'a': ['x'], 1: 'top'}, ('a', 1))
except PathAccessError as e:
    print('int trap:', repr(e.exc), e.seg, e.path)
try:
    get_path({'a': 42}, ('a','x'))
except PathAccessError as e:
    print('non-indexable:', str(e), '| type:', type(e.exc).__name__)
try:
    get_path({'a': {'b': [1]}}, ('a','b',5))
except PathAccessError as e:
    print('range:', repr(e.exc), e.seg, e.path)
print('str root:', get_path('abc', (1,)))
print('list tuple path:', get_path(['a','b','c'], (2,)))
"

